import Foundation
import CoreGraphics
import simd

/// Calculates linear impulses, angular impulses, and continuous interactive torques
/// generated by touch gestures on the fidget spinner.
enum SwipeImpulseCalculator {
    
    // MARK: - Discrete Impulse Types
    
    /// Result containing calculated impulse and induced angular velocity change for release flicks.
    struct ImpulseResult: Sendable, Equatable {
        /// Contact radius vector from center to point of application (m).
        let radiusVector: simd_float3
        /// Distance of contact from center (m).
        let leverArmDistance: Float
        /// In-plane swipe velocity (m/s).
        let swipeVelocity: simd_float3
        /// Linear impulse applied (N·s).
        let linearImpulse: simd_float3
        /// Scalar angular impulse around rotation axis (N·m·s).
        let angularImpulse: Float
        /// Induced instantaneous change in angular velocity (rad/s).
        let deltaAngularVelocity: Float
    }
    
    // MARK: - Continuous Torque Types
    
    /// Result containing calculated continuous torque and kinematic telemetry for active interactive dragging.
    struct ContinuousTorqueResult: Sendable, Equatable {
        /// Contact point in world space.
        let contactWorldPoint: simd_float3
        /// In-plane lever arm vector from rotation axis to contact point (m).
        let inPlaneRadiusVector: simd_float3
        /// Perpendicular distance from rotation axis to contact point (m).
        let leverArmDistance: Float
        /// In-plane linear velocity of finger (m/s).
        let fingerVelocity: simd_float3
        /// Tangential velocity scalar of finger along positive rotation direction (m/s).
        let tangentialVelocity: Float
        /// Target angular velocity driven by finger: ω_target = v_tan / r (rad/s).
        let targetAngularVelocity: Float
        /// Continuous torque exerted by finger along rotation axis (N·m).
        let appliedTorque: Float
        /// Whether the finger is considered stationary (< movement threshold).
        let isStationary: Bool
    }
    
    // MARK: - Continuous Torque Calculation
    
    /// Calculates the instantaneous continuous torque exerted by a finger moving across the 3D spinner.
    ///
    /// - Parameters:
    ///   - previousWorldPoint: World position of contact in previous sample.
    ///   - currentWorldPoint: World position of contact in current sample.
    ///   - previousScreenPoint: 2D screen coordinate in previous sample.
    ///   - currentScreenPoint: 2D screen coordinate in current sample.
    ///   - deltaTime: Time elapsed between samples in seconds.
    ///   - spinnerCenter: World center position of the spinner.
    ///   - rotationAxis: Unit vector of spinner rotation axis in world coordinates.
    ///   - spinnerRadius: Physical outer radius of the spinner in meters.
    ///   - momentOfInertia: Moment of inertia (I) in kg·m².
    ///   - currentAngularVelocity: Current angular velocity of the spinner (rad/s).
    ///   - effectiveMass: Effective finger mass in kg (~0.035 kg).
    ///   - spinMode: Active interaction mode (.natural maintains surface-relative traction; .continuous stacks cumulative drive torque).
    /// - Returns: `ContinuousTorqueResult` with calculated torque and kinematic telemetry.
    static func calculateContinuousTorque(
        previousWorldPoint: simd_float3,
        currentWorldPoint: simd_float3,
        previousScreenPoint: CGPoint,
        currentScreenPoint: CGPoint,
        deltaTime: TimeInterval,
        spinnerCenter: simd_float3,
        rotationAxis: simd_float3,
        spinnerRadius: Float,
        momentOfInertia: Float,
        currentAngularVelocity: Float,
        effectiveMass: Float = 0.035,
        spinMode: SpinMode = .natural
    ) -> ContinuousTorqueResult {
        let axis = VectorMath.safeNormalize(rotationAxis)
        let dt = Float(max(0.004, min(0.060, deltaTime)))
        
        // 1. Screen Movement & Stationary Check
        let dxScreen = currentScreenPoint.x - previousScreenPoint.x
        let dyScreen = currentScreenPoint.y - previousScreenPoint.y
        let screenDist = hypot(dxScreen, dyScreen)
        let screenSpeed = screenDist / CGFloat(dt)
        
        // If movement is negligible (< 0.8 pt or < 12 pt/s), finger is held stationary
        let isStationary = screenDist < 0.8 || screenSpeed < 12.0
        
        // 2. Lever Arm Vector from spinner center to current contact point
        let rawRadiusVec = currentWorldPoint - spinnerCenter
        let inPlaneRadiusVec = VectorMath.projectOntoPlane(vector: rawRadiusVec, planeNormal: axis)
        let rawRadiusDist = simd_length(inPlaneRadiusVec)
        
        // Dead zone at bearing core (< 3mm) where lever arm is too small
        if rawRadiusDist < 0.003 || isStationary {
            return ContinuousTorqueResult(
                contactWorldPoint: currentWorldPoint,
                inPlaneRadiusVector: inPlaneRadiusVec,
                leverArmDistance: rawRadiusDist,
                fingerVelocity: .zero,
                tangentialVelocity: 0.0,
                targetAngularVelocity: 0.0,
                appliedTorque: 0.0,
                isStationary: true
            )
        }
        
        // Clamp lever arm to outer radius so dragging outside doesn't create excessive torque
        let clampedDist = min(rawRadiusDist, spinnerRadius)
        let radiusVec = (inPlaneRadiusVec / rawRadiusDist) * clampedDist
        
        // 3. In-Plane Finger Displacement and Velocity
        let displacement = currentWorldPoint - previousWorldPoint
        let inPlaneDisplacement = VectorMath.projectOntoPlane(vector: displacement, planeNormal: axis)
        var velocity = inPlaneDisplacement / dt
        
        // Clamp linear velocity to realistic human flick limits (3.5 m/s)
        let speed = simd_length(velocity)
        let maxSpeed: Float = 3.5
        if speed > maxSpeed && speed > VectorMath.floatEpsilon {
            velocity = (velocity / speed) * maxSpeed
        }
        
        // 4. Tangential Velocity Scalar: (r × v) · axis / ||r||
        let crossProd = VectorMath.cross(radiusVec, velocity)
        let angularMomentumScalar = VectorMath.dot(crossProd, axis) // ||r|| * v_tan
        let vTan = angularMomentumScalar / clampedDist
        let targetOmega = vTan / clampedDist
        
        // 5. Contact Force and Dynamic Torque Modeling
        let torque: Float
        
        switch spinMode {
        case .natural:
            // Natural Spin: physical skin traction relative to spinner surface velocity.
            // When spinner moves faster than the finger, relative contact produces drag.
            let surfaceVelocity = currentAngularVelocity * clampedDist
            let relativeVelocity = vTan - surfaceVelocity
            
            // Grip traction coefficient: finger skin traction force per m/s of relative velocity
            let gripGain: Float = 0.28 // N / (m/s)
            let maxForce: Float = 0.45 // N (~45 grams of force)
            
            var force = relativeVelocity * gripGain
            force = VectorMath.clamp(force, min: -maxForce, max: maxForce)
            
            // Continuous Torque: τ = r × F (along rotation axis)
            let rawTorque = clampedDist * force
            let maxTorque: Float = 0.022
            torque = VectorMath.clamp(rawTorque, min: -maxTorque, max: maxTorque)
            
        case .continuous:
            // Continuous Spin: cumulative angular acceleration pipeline.
            // Co-directional swipes stack additive drive torque regardless of surface speed!
            // Counter-directional swipes brake and reverse.
            let isResting = abs(currentAngularVelocity) < 0.2
            let isCoDirectional = (vTan * currentAngularVelocity > 0) || isResting
            
            if isCoDirectional {
                // Swiping in the same direction of rotation (or from rest):
                // Forward drive force is strictly proportional to finger tangential velocity magnitude.
                // Surface velocity NEVER subtracts from finger speed here!
                let driveGain: Float = 0.38 // N / (m/s)
                let minDriveForce: Float = 0.08
                let maxDriveForce: Float = 0.65
                
                let swipeDirection: Float = vTan >= 0 ? 1.0 : -1.0
                let rawDriveForce = abs(vTan) * driveGain
                let clampedDriveForce = VectorMath.clamp(rawDriveForce, min: minDriveForce, max: maxDriveForce)
                let force = swipeDirection * clampedDriveForce
                
                let rawTorque = clampedDist * force
                let maxTorque: Float = 0.025
                torque = VectorMath.clamp(rawTorque, min: -maxTorque, max: maxTorque)
            } else {
                // Counter-directional swipe: user is actively swiping against rotation to brake or reverse!
                // Strong opposing torque brakes the spinner down rapidly.
                let surfaceVelocity = currentAngularVelocity * clampedDist
                let relativeVelocity = vTan - surfaceVelocity
                let brakeGain: Float = 0.35
                let maxBrakeForce: Float = 0.75
                
                var force = relativeVelocity * brakeGain
                force = VectorMath.clamp(force, min: -maxBrakeForce, max: maxBrakeForce)
                
                let rawTorque = clampedDist * force
                let maxTorque: Float = 0.025
                torque = VectorMath.clamp(rawTorque, min: -maxTorque, max: maxTorque)
            }
        }
        
        return ContinuousTorqueResult(
            contactWorldPoint: currentWorldPoint,
            inPlaneRadiusVector: radiusVec,
            leverArmDistance: clampedDist,
            fingerVelocity: velocity,
            tangentialVelocity: vTan,
            targetAngularVelocity: targetOmega,
            appliedTorque: torque,
            isStationary: false
        )
    }
    
    // MARK: - Discrete Impulse Calculation
    
    /// Computes rotational impulse from a swipe motion between two world points on the spinner plane.
    /// - Parameters:
    ///   - startWorldPoint: World position where swipe segment started.
    ///   - endWorldPoint: World position where swipe segment ended.
    ///   - duration: Time duration of the swipe segment in seconds.
    ///   - spinnerCenter: World center position of the spinner.
    ///   - rotationAxis: Unit vector of spinner rotation axis in world coordinates.
    ///   - spinnerRadius: Physical outer radius of the spinner in meters.
    ///   - momentOfInertia: Moment of inertia (I) in kg·m².
    ///   - effectiveMass: Effective finger mass in kg (~0.035 kg).
    /// - Returns: `ImpulseResult` containing angular impulse and Δω.
    static func calculateImpulse(
        startWorldPoint: simd_float3,
        endWorldPoint: simd_float3,
        duration: TimeInterval,
        spinnerCenter: simd_float3,
        rotationAxis: simd_float3,
        spinnerRadius: Float,
        momentOfInertia: Float,
        effectiveMass: Float
    ) -> ImpulseResult {
        let axis = VectorMath.safeNormalize(rotationAxis)
        let dt = Float(max(duration, 0.004)) // Avoid division by zero (minimum 4ms)
        
        // 1. Calculate contact point as midpoint of the swipe segment
        let rawContactPoint = (startWorldPoint + endWorldPoint) * 0.5
        var rawRadiusVec = rawContactPoint - spinnerCenter
        
        // Project contact point onto the plane to ensure zero out-of-plane component
        rawRadiusVec = VectorMath.projectOntoPlane(vector: rawRadiusVec, planeNormal: axis)
        
        let rawDist = simd_length(rawRadiusVec)
        
        // Clamp lever arm to outer radius so dragging far outside doesn't create unrealistic torque
        let clampedDist = min(rawDist, spinnerRadius)
        let radiusVec: simd_float3
        if rawDist > VectorMath.floatEpsilon {
            radiusVec = (rawRadiusVec / rawDist) * clampedDist
        } else {
            radiusVec = simd_float3(0, 0, 0)
        }
        
        // 2. In-plane swipe displacement and velocity
        let displacement = endWorldPoint - startWorldPoint
        let inPlaneDisplacement = VectorMath.projectOntoPlane(vector: displacement, planeNormal: axis)
        var velocity = inPlaneDisplacement / dt
        
        // Clamp velocity magnitude to prevent unrealistic impulse spikes from touch glitches
        let speed = simd_length(velocity)
        let maxSpeed: Float = 3.5 // 3.5 m/s (~12.6 km/h) max realistic finger swipe speed
        if speed > maxSpeed && speed > VectorMath.floatEpsilon {
            velocity = (velocity / speed) * maxSpeed
        }
        
        // 3. Linear impulse: J = m_eff * v
        let linearImpulse = velocity * effectiveMass
        
        // 4. Angular impulse vector: ΔL = r × J
        let angularImpulseVec = VectorMath.cross(radiusVec, linearImpulse)
        
        // 5. Scalar angular impulse along the rotation axis:
        // ΔL_axis = (r × J) · axis
        let scalarAngularImpulse = VectorMath.dot(angularImpulseVec, axis)
        
        // 6. Δω = ΔL_axis / I
        let safeInertia = max(1e-7, momentOfInertia)
        let deltaOmega = scalarAngularImpulse / safeInertia
        
        return ImpulseResult(
            radiusVector: radiusVec,
            leverArmDistance: clampedDist,
            swipeVelocity: velocity,
            linearImpulse: linearImpulse,
            angularImpulse: scalarAngularImpulse,
            deltaAngularVelocity: deltaOmega
        )
    }
}
